import{_ as a,c as e,o,a1 as t,a4 as l,a5 as i,a6 as c}from"./chunks/framework.7AAjiCkA.js";const f=JSON.parse('{"title":"V2 客户端功能","description":"","frontmatter":{},"headers":[],"relativePath":"V2/V2 客户端功能.md","filePath":"V2/V2 客户端功能.md"}'),d={name:"V2/V2 客户端功能.md"},r=t('<h1 id="v2-客户端功能" tabindex="-1">V2 客户端功能 <a class="header-anchor" href="#v2-客户端功能" aria-label="Permalink to &quot;V2 客户端功能&quot;">​</a></h1><p>用户可以在 <code>X-Chat V2 用户API授权中心</code> 查看所有令牌的使用信息，包括：</p><ul><li>每次对话的时间</li><li>对话所用令牌名称</li><li>对话使用的模型</li><li>对话产生的额度及详情</li><li>账户操作</li></ul><p>该功能为二次售卖的用户提供了审计的功能，便于进行管理。</p><h2 id="查看剩余额度及兑换额度" tabindex="-1">查看剩余额度及兑换额度 <a class="header-anchor" href="#查看剩余额度及兑换额度" aria-label="Permalink to &quot;查看剩余额度及兑换额度&quot;">​</a></h2><ul><li>用户可以点击X-Chat页面菜单栏的 <code>可用余额</code> 来查看当前会员信息及额度信息等基础内容，如下：</li></ul><p><img src="'+l+'" alt="额度"></p><ul><li>也可以在 <code>X-Chat V2 用户API授权中心</code> 的 <code>充值</code> 页面中查看当前账户剩余额度等详细内容。</li></ul><h2 id="购买额度" tabindex="-1">购买额度 <a class="header-anchor" href="#购买额度" aria-label="Permalink to &quot;购买额度&quot;">​</a></h2><p>购买额度：<a href="https://shop.basetec.top" target="_blank" rel="noreferrer">点此前往</a>。</p><h2 id="x-chat-v2-聊天记录云同步" tabindex="-1">X-Chat V2 聊天记录云同步 <a class="header-anchor" href="#x-chat-v2-聊天记录云同步" aria-label="Permalink to &quot;X-Chat V2 聊天记录云同步&quot;">​</a></h2><h3 id="主要特性" tabindex="-1">主要特性： <a class="header-anchor" href="#主要特性" aria-label="Permalink to &quot;主要特性：&quot;">​</a></h3><ol><li><p>由 <code>X-Chat官方</code> 提供云服务，用户可以直接使用。拥有极快的同步速度，同时不限制同步设备数；</p></li><li><p>采用 <code>WebDev协议</code> ，用户聊天数据经过多重加密。X-Chat官方不存储用户隐私数据。如想了解更多细节，请在X-Chat中询问您的智能助手；</p></li><li><p>实时、无感知同步数据，多台设备的数据实时在话题记录中显示，无需刷新页面，保证用户使用体验；</p></li><li><p>同步后，在原有记录基础上进行合并，不会覆盖原有记录；</p></li></ol><h3 id="注意事项" tabindex="-1">注意事项： <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项：&quot;">​</a></h3><ol><li><p>用户需要在 <code>X-Chat V2</code> 版本使用；</p></li><li><p>为了彻底地保护用户隐私，用户的聊天数据将不会存储在X-Chat的服务器，在同步时也不会经过X-Chat，因此在同步时需要注意：</p><p>在 <code>A设备</code> 使用后，如果想在 <code>B设备</code> 同步聊天记录，在同步时需要保证 <code>A设备</code> 和 <code>B设备</code> 的 <code>X-Chat聊天客户端</code> 均处于<strong>打开</strong>状态。两台以上设备进行同步同理。</p></li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>你可以理解为只可以在线点对点传输数据，这种方法保证了用户隐私数据在同步过程中只会经过用户这几台设备。</p></div><h3 id="使用方法" tabindex="-1">使用方法： <a class="header-anchor" href="#使用方法" aria-label="Permalink to &quot;使用方法：&quot;">​</a></h3><ol><li><p>进入X-Chat V2站点；</p></li><li><p>点击左上角 <code>同步未开启</code> ，点击 <code>配置同步参数</code> ；</p></li></ol><p><img src="'+i+'" alt="配置同步"></p><ol start="3"><li>在打开的页面中，在上方设备信息中可以设置 <code>本设备名称</code> （选填），在 <code>同步频道名称</code> 中输入一个你自定义的用户名，在 <code>同步频道密码</code> 中填写你要设置的密码。输入完成后勾选 <code>开启同步</code> 按钮；</li></ol><p><img src="'+c+'" alt="配置同步"></p><ol start="4"><li>成功登录后，你可以在聊天页面左上角中看到当前设备在线列表及同步状态。</li></ol>',22),h=[r];function s(p,n,_,u,m,b){return o(),e("div",null,h)}const C=a(d,[["render",s]]);export{f as __pageData,C as default};
